/// The host's print for the chapter's Console lines (UTF-8, valid during
/// the call); null, they go nowhere.
pub var cx_host_print: ?*const fn ([]const u8) void = null;

/// What a host calls besides the exports.
pub const cx = struct {
    /// The Codex heap's region, given before the first allocation and kept:
    /// zeroed, as bare metal's boot zero-fills its heap. The same region
    /// again changes nothing.
    pub fn heapGive(region: []align(4096) u8) void {
        if (cx_heap_mem.len != 0) {
            if (cx_heap_mem.ptr == region.ptr and cx_heap_mem.len == region.len) return;
            @panic("cx heap: the heap already has its region");
        }
        cx_heap_mem = region;
        cx_heap_reserve = region.len;
    }

    /// Bytes in use since the heap's base, garbage included.
    pub fn heapUsed() i64 {
        return cx_hp - 6291456;
    }

    /// The frontier now, to go back to with `heapBack`.
    pub fn heapMark() i64 {
        return cx_hp;
    }

    /// Everything allocated after `mark_at` given back: nothing kept may live there.
    pub fn heapBack(mark_at: i64) void {
        if (mark_at < 6291456 or mark_at > cx_hp) @panic("cx heap: a mark that is not behind the frontier");
        cx_hp = mark_at;
    }

    /// Everything given back.
    pub fn heapReset() void {
        cx_hp = 6291456;
    }

