    const host = cx_file_host orelse return out;
    var names = std.mem.splitScalar(u8, host.list(cx_cce_to_utf8(path)), '\n');
    while (names.next()) |name| {
        if (name.len > 0) _ = cx_ll_push(out, cx_utf8_to_cce(name));
    }
    return out;
}
fn cx_fs_make_dir(path: []const u8) bool {
    const host = cx_file_host orelse return false;
    return host.make_dir(cx_cce_to_utf8(path));
}
